          value: data['email']
        }
      } as ItemSelectItem;
      this.member.users.push(item);
    });
  }

  /** Format Roles in Item format */
  formatRoles() {
    this.rolesData.forEach(data => {
      const translatedLabel = this.labelTranslationService.translateRole(data);
      this.roleTranslationMap.set(data, translatedLabel);
      let item = {
        key: data,
        label: translatedLabel
      } as ItemSelectItem;
      this.member.roles.push(item);
    });
  }

  /** Get localized role name from English key */
  getLocalizedRoleName(role: string): string {
    return this.roleTranslationMap.get(role) || role;
  }

  /** On Cancel Button Click */
  onCancel() {
    this.modalService.close();
  }

  /** Search Users*/
  searchUsers(searchTerm: string): Observable<ItemSelectItem[]> {
    let tempItem = this.member.users.filter(data => {
      let isAvailable = false;
      if (Array.isArray(searchTerm)) {
        searchTerm.forEach(searchData => {
          if (isAvailable) {
            return true;
          }
          isAvailable = this.isMemberAvailable(data, searchData);
        });
      } else {
        isAvailable = this.isMemberAvailable(data, searchTerm) || searchTerm == '';
      }
      if (isAvailable) {
        return true;
      }
    });

    return of(tempItem);
  }

  /** Search Roles */
  searchRoles(searchTerm: any): Observable<ItemSelectItem[]> {
    let tempItem = this.member.roles.filter(data => {
      let isAvailable = false;
      if (Array.isArray(searchTerm)) {
        searchTerm.forEach(searchData => {
          if (isAvailable) {
            return true;
          }
          isAvailable = this.isMemberAvailable(data, searchData);
        });
      } else {
        isAvailable = this.isMemberAvailable(data, searchTerm) || searchTerm == '';
      }
      if (isAvailable) {
        return true;
      }
    });
    return of(tempItem);
  }

  searchData(searchTerm: any): Observable<ItemSelectItem[]> {
    let tempItem = this.organizationItems.filter(data => {
      let isAvailable =
        (null != data.key && data.key.indexOf(searchTerm) > -1) ||
        (null != data.label && data.label.toLowerCase().indexOf(searchTerm) > -1) ||
        searchTerm == '';
      if (isAvailable) {
        return true;
      }
    });
    return of(tempItem);
  }

  /** Check if Member is available */
  isMemberAvailable(data, searchTerm) {
    return (
      (null != data.key && data.key.indexOf(searchTerm) > -1) ||
      (null != data.label && data.label.toLowerCase().indexOf(searchTerm) > -1) ||
      (null != data.subLabel && data.subLabel.toLowerCase().indexOf(searchTerm) > -1)
    );
  }

  /** Update the Item dropdown */
  userItemSelect = {
    placeholder: this.translateService.instant('member.placeholder.msg'),
    options: <ItemSelectOptions>{
      functionList: term => this.searchUsers(term),
      multiSelect: true
    }
  };

  /** Update the Item dropdown */
  roleItemSelect = {
    placeholder: this.translateService.instant('member.placeholder.select.role'),
    options: <ItemSelectOptions>{
      functionList: term => this.searchRoles(term),
      multiSelect: true
    }
  };

  organizationItemSelect = {
    placeholder: this.translateService.instant('member.placeholder.select.organization'),
    options: <ItemSelectOptions>{
      functionList: term => this.searchData(term),
      multiSelect: false
    }
  };

  onUserSelect(searchData) {
    this.isExistingMember = false;
    this.existingOrganizationName = '';
    // Clear previously selected users
    this.member.selectedUsers = [];

    // Check if searchData is an event or empty string, if so, return
    if (searchData instanceof Event || !searchData) {
      return;
    }

    // Ensure searchData is an array to handle multiple selections
    if (!Array.isArray(searchData)) {
      searchData = [searchData];
    }

    // Only check for project membership if a single user is selected
    if (searchData.length === 1) {
      this.checkProjectMembership(searchData[0]);
    }

    searchData.forEach(searchDataElement => {
      let user = this.member.users.find(user => user.key === searchDataElement);
      if (!user) {
        // If the user is not found in the users list, add it as a new user
        user = {
          key: searchDataElement,
          label: searchDataElement,
          subLabel: searchDataElement,
          graphic: {
            type: ItemGraphicType.LOGO,
            value: searchDataElement
          },
          isNotInList: true
        } as ItemSelectItem;
        this.member.users.push(user);
      }
      this.member.selectedUsers.push(user);
    });
  }

  checkProjectMembership(userId: string) {
    if (this.currProject && this.currProject.id && userId) {
      const sub = this.contractService.getProjectMembership(this.currProject.id, userId).subscribe(
        (response: { isMember: boolean; organizationName: string }) => {
          this.isExistingMember = response.isMember;
          this.existingOrganizationName = response.organizationName;
        },
        error => {
          console.error('Error checking project membership:', error);
          this.isExistingMember = false;
          this.existingOrganizationName = '';
        }
      );
      this.currObs.push(sub);
    }
  }

  onRoleSelect(searchData) {
    if (searchData instanceof Event) {
      return;
    }
    let sr = this.searchRoles(searchData).subscribe(data => {
      this.member.selectedRoles = data;
    });
    this.currObs.push(sr);
  }

  onMemberAdd() {
    this.errorUser = [];
    this.userExistError = false;
    let tempDisplayedUsers = JSON.stringify(this.displayedMembers); //Already displayed users
    this.member.users = this.member.users.filter(data => {
      //Remove users which are added to selected Users
      let isAvailable = false;
      this.member.selectedUsers.filter(sdata => {
        if (data.key === sdata.key) {
          isAvailable = true;
        }
      });
      return !isAvailable;
    });
    const userEmailMap = new Map<string, any>();
    let gc = this.getContractMembers().subscribe(result => {
      result.forEach(user => userEmailMap.set(user.userEmail, user));
      this.member.selectedUsers.forEach(selectedMember => {
        if (tempDisplayedUsers.indexOf(selectedMember.key) != -1) {
          this.userExistError = true;
          this.errorUser.push(selectedMember.key);
        } else {
          let displayedMember: DisplayedMember = {
            user: selectedMember,
            roles: this.member.selectedRoles.map(x => x.key),
            organization: this.isExistingMember ? this.existingOrganizationName : this.selectedOrg
          };
          if (
            displayedMember.roles.includes(RoleConstant.REVIEWER_KEY) &&
            !displayedMember.roles.includes(RoleConstant.COORDINATOR_KEY) &&
            !displayedMember.roles.includes(RoleConstant.MEMBER_KEY)
          ) {
            displayedMember.roles.push(RoleConstant.MEMBER_KEY);
          }
          displayedMember.localizedRoles = displayedMember.roles.map(r => this.labelTranslationService.translateRole(r));
          if (userEmailMap) {
            if (userEmailMap.has(selectedMember.subLabel)) {
              this.userExistError = true;
              this.member.users.push(displayedMember.user);
              this.errorUser.push(selectedMember.subLabel);
            } else {
              this.displayedMembers.push(displayedMember);
            }
          } else {
            this.displayedMembers.push(displayedMember);
          }
          this.currObs.push(gc);
        }
      });
      // Clear selected users and roles after adding
      this.member.selectedUsers = [];
      this.member.selectedRoles = [];
      this.selectedOrg = '';
      this.removeAllItems();
    });
  }

  removeAllItems(): void {
    this.clearItem.next(null);
  }

  removeDisplayedItem(item) {
    this.displayedMembers = this.displayedMembers.filter(data => {
      if (data.user != item.user) {
        return true;
      }
    });
    //  this.selectedOrg = '';
    this.member.users.push(item.user);
  }

  /** Get Contract Members
   */
  getContractMembers(): Observable<any[]> {
    return this.contractService
      .getContractMembers({
        contractId: { eq: this.currContract?.id },
        fetchLastLoginInfo: true
      })
      .pipe(
        map(res => {
          return res.map(mem => {
            if (mem.lastLogin === 'INVITATION_PENDING') {
              mem.user = [mem.userEmail];
              mem.lastLogin = CommonConstant.USER_STATUS;
            } else {
              mem.user = [mem.userName, mem.userEmail];
              mem.lastLogin = this.translateService.instant('memeber.last.login.msg') + mem.lastLogin;
            }
            return mem;
          });
        })
      );
  }

  saveMember() {
    let contractUsers: ContractMember[] = [];
    this.isloading = true;
    this.displayedMembers.forEach(userData => {
      let user: ContractMember = {
        userEmail: userData.user.subLabel,
        companyName: userData.organization,
        roleName: userData.roles
      };
      contractUsers.push(user);
    });

    let contractMembers = {
      projectId: this.currProject?.id,
      contractId: this.currContract?.id,
      members: contractUsers
    };
    let ms = this.memberService.addContractMembers(contractMembers).subscribe(
      result => {
        this.isloading = false;
        this.contractService.refreshContractMembers();
        this.notifService.notifySuccess(this.translateService.instant('member.success.msg'));
        this.modalService.close();
      },
      errors => {
        this.isloading = false;
        this.notifService.notifyError(this.translateService.instant('add-member-error'));
      }
    );
    this.currObs.push(ms);
  }

  /** Get Project Organization
   */
  getOrganizationData() {
    let options: any = {};
    options.list = [];

    let o = this.orgService.getActiveOrganizations(this.currProject.id).subscribe(response => {
      response.forEach(element => {
        let item: ItemSelectItem = {
          key: element.name,
          label: element.name
        };
        options.list.push(element.name);
        this.organizationItems.push(item);
      });
      this.member.organization = options;
    });
    this.currObs.push(o);
  }

  onOrgChange(event) {
    this.selectedOrg = event;
  }

  removeError() {
    this.userExistError = false;
  }

  isArrayEquals(a1, a2) {
    const superSet = {};
    for (const i of a1) {
      const e = i + typeof i;
      superSet[e] = 1;
    }
    for (const i of a2) {
      const e = i + typeof i;
      if (!superSet[e]) {
        return false;
      }
      superSet[e] = 2;
    }
    for (let e in superSet) {
      if (superSet[e] === 1) {
        return false;
      }
    }
    return true;
  }

  /** Notify error message for an invalid email address*/
  onNewItemSelect(isValidEmail) {
    if (isValidEmail) {
      let item = {
        key: this.userSelectComponent.searchTerm,
        label: this.userSelectComponent.searchTerm,
        subLabel: sessionStorage.getItem('email'),
        graphic: {
          type: ItemGraphicType.LOGO,
          value: this.userSelectComponent.searchTerm
        },
        isNotInList: true
      } as ItemSelectItem;
      this.newUser = item;
    } else {
      this.notifService.notifyError(this.translateService.instant('invalid-member-email-error'));
    }
  }

  getButtonLabel(keyName: string): string {
    return this.utilityService.getLocalizedValue(keyName);
  }
}
